import { getRegistry, getComponentName } from '@saffron/config';
import { promptTemplate } from './prompt.template.js';
import { styles } from './prompt.styles.js';
import { Prompt } from './prompt.js';
import SafButton from '../button/define.js';
import SafIcon from '../icon/define.js';
import SafTextArea from '../text-area/define.js';
import SafProgressText from '../progress-text/define.js';

const safAIPromptConfig = {
    events: {
        onInput: 'input',
        onChange: 'change',
        onSend: 'send',
        onStop: 'stop',
    },
};
const promptDefine = () => {
    SafButton();
    SafIcon();
    SafTextArea();
    SafProgressText();
    return Prompt.define({
        name: getComponentName('saf-ai-prompt'),
        template: promptTemplate(),
        styles: styles(),
        registry: getRegistry(),
    });
};

export { promptDefine as default, safAIPromptConfig };
